-- Canonical Festival upgrade catalogue v1. Money is integer minor units.
CREATE TABLE public.festival_upgrade_catalogue_versions(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version integer UNIQUE NOT NULL CHECK(version>0), status text NOT NULL CHECK(status IN('draft','published','retired')),
 effective_from timestamptz NOT NULL, retired_at timestamptz, admin_notes text, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz,
 CHECK(status<>'published' OR published_at IS NOT NULL)
);
CREATE UNIQUE INDEX festival_one_active_upgrade_catalogue ON public.festival_upgrade_catalogue_versions((status)) WHERE status='published' AND retired_at IS NULL;
CREATE TABLE public.festival_upgrade_categories(
 key text PRIMARY KEY CHECK(key~'^[a-z][a-z0-9_]+$'), display_order smallint UNIQUE NOT NULL CHECK(display_order BETWEEN 1 AND 11), display_name text NOT NULL, description text NOT NULL, gameplay_consumers text[] NOT NULL CHECK(cardinality(gameplay_consumers)>0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.festival_upgrade_levels(
 catalogue_version integer NOT NULL REFERENCES public.festival_upgrade_catalogue_versions(version), category_key text NOT NULL REFERENCES public.festival_upgrade_categories(key), level smallint NOT NULL CHECK(level BETWEEN 1 AND 5), level_name text NOT NULL,
 purchase_cost_minor bigint NOT NULL CHECK(purchase_cost_minor>0), weekly_upkeep_minor bigint NOT NULL CHECK(weekly_upkeep_minor>=0), build_duration interval NOT NULL CHECK(build_duration>=interval '0'), minimum_licence_tier smallint NOT NULL DEFAULT 0 CHECK(minimum_licence_tier BETWEEN 0 AND 5), minimum_company_reputation integer NOT NULL DEFAULT 0 CHECK(minimum_company_reputation>=0), effects jsonb NOT NULL CHECK(jsonb_typeof(effects)='object'), effective_from timestamptz NOT NULL, retired_at timestamptz, active boolean NOT NULL DEFAULT true, admin_notes text, PRIMARY KEY(catalogue_version,category_key,level)
);
CREATE TABLE public.festival_upgrade_prerequisites(catalogue_version integer NOT NULL,category_key text NOT NULL,level smallint NOT NULL,prerequisite_category_key text NOT NULL,prerequisite_level smallint NOT NULL CHECK(prerequisite_level BETWEEN 1 AND 5),PRIMARY KEY(catalogue_version,category_key,level,prerequisite_category_key),FOREIGN KEY(catalogue_version,category_key,level) REFERENCES public.festival_upgrade_levels(catalogue_version,category_key,level),FOREIGN KEY(catalogue_version,prerequisite_category_key,prerequisite_level) REFERENCES public.festival_upgrade_levels(catalogue_version,category_key,level),CHECK(category_key<>prerequisite_category_key));
CREATE TABLE public.festival_licence_tiers(key text PRIMARY KEY,rank smallint UNIQUE NOT NULL CHECK(rank BETWEEN 1 AND 5),display_name text NOT NULL,max_attendance integer NOT NULL,max_days smallint NOT NULL,max_stages smallint NOT NULL,max_acts_per_day smallint NOT NULL,camping_allowed boolean NOT NULL,minimum_reputation integer NOT NULL,fee_minor bigint NOT NULL,validity interval NOT NULL,requirements jsonb NOT NULL CHECK(jsonb_typeof(requirements)='object'),active boolean NOT NULL DEFAULT true);
CREATE TABLE public.festival_company_licences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),tier_key text NOT NULL REFERENCES public.festival_licence_tiers(key),status text NOT NULL CHECK(status IN('pending','active','suspended','expired','revoked')),applied_at timestamptz NOT NULL DEFAULT now(),valid_from timestamptz,valid_until timestamptz,decision_reason text,decided_by uuid REFERENCES public.profiles(id),UNIQUE(festival_company_id,tier_key,status));
ALTER TABLE public.festival_companies ADD COLUMN upgrade_version integer NOT NULL DEFAULT 0 CHECK(upgrade_version>=0), ADD COLUMN upgrade_delinquent boolean NOT NULL DEFAULT false;
CREATE TABLE public.festival_company_upgrades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),category_key text NOT NULL REFERENCES public.festival_upgrade_categories(key),catalogue_version integer NOT NULL,owned_level smallint NOT NULL CHECK(owned_level BETWEEN 1 AND 5),active_level smallint NOT NULL CHECK(active_level BETWEEN 0 AND owned_level),status text NOT NULL CHECK(status IN('purchased','building','active','cancelled','failed')),build_started_at timestamptz,build_completes_at timestamptz,activated_at timestamptz,missed_upkeep_weeks integer NOT NULL DEFAULT 0 CHECK(missed_upkeep_weeks>=0),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(festival_company_id,category_key),FOREIGN KEY(catalogue_version,category_key,owned_level) REFERENCES public.festival_upgrade_levels(catalogue_version,category_key,level));
CREATE TABLE public.festival_upgrade_purchase_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),actor_profile_id uuid NOT NULL REFERENCES public.profiles(id),category_key text NOT NULL,requested_level smallint NOT NULL,idempotency_key uuid NOT NULL,payload_hash text NOT NULL,status text NOT NULL CHECK(status IN('processing','succeeded','failed')),catalogue_version integer NOT NULL,company_version integer NOT NULL,amount_minor bigint NOT NULL,financial_transaction_id uuid REFERENCES public.financial_transactions(id),result jsonb,failure_code text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(actor_profile_id,idempotency_key));
CREATE TABLE public.festival_upgrade_effect_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_operation_id uuid UNIQUE REFERENCES public.festival_upgrade_purchase_operations(id),festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),category_key text NOT NULL,owned_level smallint NOT NULL,active_level smallint NOT NULL,effective_level smallint NOT NULL,effects jsonb NOT NULL,catalogue_version integer NOT NULL,aggregate_version integer NOT NULL,snapshot_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_upgrade_upkeep_obligations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),category_key text NOT NULL,owned_level smallint NOT NULL,billing_period date NOT NULL,amount_minor bigint NOT NULL,status text NOT NULL CHECK(status IN('due','paid','unpaid','waived')),financial_transaction_id uuid REFERENCES public.financial_transactions(id),failure_reason text,idempotency_reference text NOT NULL UNIQUE,paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(festival_company_id,category_key,billing_period));
CREATE TABLE public.festival_edition_upgrade_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),edition_id uuid NOT NULL,festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),snapshot_version integer NOT NULL DEFAULT 1,catalogue_version integer NOT NULL,source_aggregate_version integer NOT NULL,licence_snapshot jsonb NOT NULL,levels jsonb NOT NULL,resolved_effects jsonb NOT NULL,delinquency_modifiers jsonb NOT NULL,snapshot_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),supersedes_id uuid REFERENCES public.festival_edition_upgrade_snapshots(id),override_reason text,UNIQUE(edition_id,snapshot_version));
CREATE TABLE public.festival_upgrade_audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,festival_company_id uuid,actor_profile_id uuid,event_type text NOT NULL,reason text,before_value jsonb,after_value jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_upgrade_legacy_migrations(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,festival_company_id uuid NOT NULL,source_table text NOT NULL,source_value jsonb NOT NULL,category_key text,canonical_level smallint,mapping_version integer NOT NULL,mapping_quality text NOT NULL CHECK(mapping_quality IN('exact','inferred','ambiguous','unmapped')),requires_review boolean NOT NULL,migrated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(festival_company_id,source_table,category_key));

INSERT INTO public.festival_upgrade_catalogue_versions(version,status,effective_from,published_at,admin_notes) VALUES(1,'published','2026-07-28',now(),'Initial canonical eleven-category catalogue');
INSERT INTO public.festival_upgrade_categories(key,display_order,display_name,description,gameplay_consumers) VALUES
('site_infrastructure',1,'Site Infrastructure','Safe, resilient site preparation and attendance infrastructure.',ARRAY['planning','ticketing','runtime']),('stages_production',2,'Stages and Production','Stages, sound, lighting and technical production.',ARRAY['planning','runtime']),('security_crowd_control',3,'Security and Crowd Control','Barriers, access control and crowd command.',ARRAY['planning','runtime']),('medical_welfare',4,'Medical and Welfare','Medical response, first aid and welfare provision.',ARRAY['planning','runtime']),('sanitation_utilities',5,'Sanitation and Utilities','Water, toilets, power and waste systems.',ARRAY['planning','runtime','settlement']),('artist_backstage',6,'Artist and Backstage Facilities','Dressing rooms, catering and backstage logistics.',ARRAY['planning','runtime']),('audience_facilities',7,'Audience Facilities','Customer facilities, queues, food, drink and VIP provision.',ARRAY['ticketing','runtime','settlement']),('camping_accommodation',8,'Camping and Accommodation','Campsites, showers and overnight products.',ARRAY['planning','ticketing','settlement']),('transport_access',9,'Transport and Access','Parking, shuttles, loading and public transport coordination.',ARRAY['planning','ticketing','runtime']),('marketing_media',10,'Marketing and Media','Demand generation, media reach and sponsor visibility.',ARRAY['ticketing','runtime','settlement']),('sustainability_technology',11,'Sustainability and Technology','Efficient energy, waste, connectivity and cashless operations.',ARRAY['runtime','settlement']);
WITH costs(level,cost,upkeep,hours) AS (VALUES(1,500000::bigint,10000::bigint,24),(2,1500000,30000,72),(3,4000000,80000,168),(4,10000000,200000,336),(5,25000000,500000,720)), mult(key,m) AS (VALUES('site_infrastructure',1.30),('stages_production',1.50),('security_crowd_control',1.20),('medical_welfare',1.10),('sanitation_utilities',1.15),('artist_backstage',1.05),('audience_facilities',1.00),('camping_accommodation',1.10),('transport_access',1.10),('marketing_media',1.00),('sustainability_technology',1.25))
INSERT INTO public.festival_upgrade_levels(catalogue_version,category_key,level,level_name,purchase_cost_minor,weekly_upkeep_minor,build_duration,minimum_licence_tier,minimum_company_reputation,effects,effective_from)
SELECT 1,m.key,c.level,(ARRAY['Basic','Established','Professional','Major','World Class'])[c.level],round(c.cost*m.m),round(c.upkeep*m.m),make_interval(hours=>c.hours),greatest(0,c.level-1),greatest(0,(c.level-1)*100),jsonb_build_object('capacity',c.level*5000,'qualityBasisPoints',c.level*1500,'riskReductionBasisPoints',c.level*700,'revenueBasisPoints',c.level*300),now() FROM costs c CROSS JOIN mult m;
INSERT INTO public.festival_licence_tiers VALUES
('local',1,'Local',5000,1,1,8,false,0,100000,interval '1 year','{"site_infrastructure":1,"stages_production":1,"security_crowd_control":1,"medical_welfare":1}',true),('small',2,'Small',15000,2,2,12,false,100,300000,interval '1 year','{"site_infrastructure":2,"stages_production":2,"security_crowd_control":2,"medical_welfare":2,"audience_facilities":1,"transport_access":1}',true),('medium',3,'Medium',40000,3,3,18,true,300,750000,interval '1 year','{"site_infrastructure":3,"stages_production":3,"security_crowd_control":3,"medical_welfare":3,"artist_backstage":2,"audience_facilities":2}',true),('large',4,'Large',80000,4,5,25,true,600,1500000,interval '1 year','{"site_infrastructure":4,"stages_production":4,"security_crowd_control":4,"medical_welfare":4,"sanitation_utilities":4,"artist_backstage":3,"transport_access":3}',true),('major',5,'Major',150000,5,8,35,true,1000,3000000,interval '1 year','{"site_infrastructure":5,"stages_production":5,"security_crowd_control":5,"medical_welfare":5,"sanitation_utilities":5,"artist_backstage":4,"audience_facilities":4,"transport_access":4,"marketing_media":3,"sustainability_technology":3}',true);

CREATE FUNCTION public._festival_upgrade_actor() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE p uuid;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_ACCESS_DENIED' USING ERRCODE='P0001';END IF;p:=public.current_profile_id_safe();IF p IS NULL THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_ACCESS_DENIED' USING ERRCODE='P0001';END IF;RETURN p;END$$;
CREATE FUNCTION public._festival_upgrade_authorised(c uuid,a uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT EXISTS(SELECT 1 FROM public.festival_companies f WHERE f.id=c AND (f.owner_profile_id=a OR public.can_manage_company(f.company_id)))$$;
CREATE FUNCTION public._festival_effective_level(owned int,active int,missed int) RETURNS int LANGUAGE sql IMMUTABLE AS $$SELECT CASE WHEN missed>=4 THEN greatest(0,least(active,owned-1)) ELSE active END$$;
CREATE FUNCTION public._festival_upgrade_category_json(c uuid,k text,v int) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT jsonb_build_object('key',cat.key,'displayName',cat.display_name,'description',cat.description,'ownedLevel',coalesce(u.owned_level,0),'activeLevel',coalesce(u.active_level,0),'effectiveLevel',public._festival_effective_level(coalesce(u.owned_level,0),coalesce(u.active_level,0),coalesce(u.missed_upkeep_weeks,0)),'status',coalesce(u.status,'not_installed'),'currentUpkeepMinor',coalesce(cur.weekly_upkeep_minor,0),'nextLevel',n.level,'nextCostMinor',n.purchase_cost_minor,'nextUpkeepMinor',n.weekly_upkeep_minor,'buildDurationHours',extract(epoch from n.build_duration)::bigint/3600,'effects',coalesce(cur.effects,'{}'),'nextEffects',n.effects,'missingRequirements','[]'::jsonb,'affordable',coalesce(a.available_balance_minor,0)>=coalesce(n.purchase_cost_minor,0),'delinquent',coalesce(u.missed_upkeep_weeks,0)>0) FROM public.festival_upgrade_categories cat LEFT JOIN public.festival_company_upgrades u ON u.festival_company_id=c AND u.category_key=cat.key LEFT JOIN public.festival_upgrade_levels cur ON cur.catalogue_version=v AND cur.category_key=cat.key AND cur.level=u.active_level LEFT JOIN public.festival_upgrade_levels n ON n.catalogue_version=v AND n.category_key=cat.key AND n.level=coalesce(u.owned_level,0)+1 LEFT JOIN public.festival_companies fc ON fc.id=c LEFT JOIN public.financial_accounts a ON a.owner_type='company' AND a.owner_id=fc.company_id AND a.is_primary WHERE cat.key=k$$;
CREATE FUNCTION public.get_festival_company_upgrades(p_festival_company_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_upgrade_actor();v int;fc public.festival_companies%ROWTYPE;BEGIN SELECT * INTO fc FROM public.festival_companies WHERE id=p_festival_company_id;IF fc.id IS NULL OR NOT public._festival_upgrade_authorised(fc.id,a) THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_ACCESS_DENIED' USING ERRCODE='P0001';END IF;SELECT version INTO v FROM public.festival_upgrade_catalogue_versions WHERE status='published' AND retired_at IS NULL;RETURN jsonb_build_object('festivalCompanyId',fc.id,'catalogueVersion',v,'companyVersion',fc.upgrade_version,'currencyCode','GBP','availableBalanceMinor',coalesce((SELECT available_balance_minor FROM public.financial_accounts WHERE owner_type='company' AND owner_id=fc.company_id AND is_primary),0),'categories',(SELECT jsonb_agg(public._festival_upgrade_category_json(fc.id,key,v) ORDER BY display_order) FROM public.festival_upgrade_categories WHERE active),'licence',public.get_festival_licence_progress(fc.id));END$$;
CREATE FUNCTION public.get_festival_upgrade_catalogue() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT jsonb_build_object('version',v.version,'categories',(SELECT jsonb_agg(to_jsonb(c)||jsonb_build_object('levels',(SELECT jsonb_agg(to_jsonb(l) ORDER BY level) FROM public.festival_upgrade_levels l WHERE l.catalogue_version=v.version AND l.category_key=c.key AND l.active)) ORDER BY c.display_order) FROM public.festival_upgrade_categories c WHERE c.active)) FROM public.festival_upgrade_catalogue_versions v WHERE v.status='published' AND v.retired_at IS NULL$$;
CREATE FUNCTION public.get_festival_licence_progress(p_festival_company_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$WITH levels AS(SELECT category_key,active_level FROM public.festival_company_upgrades WHERE festival_company_id=p_festival_company_id),eligible AS(SELECT t.* FROM public.festival_licence_tiers t WHERE t.active AND NOT EXISTS(SELECT 1 FROM jsonb_each_text(t.requirements) r LEFT JOIN levels l ON l.category_key=r.key WHERE coalesce(l.active_level,0)<r.value::int)),current AS(SELECT l.*,t.display_name FROM public.festival_company_licences l JOIN public.festival_licence_tiers t ON t.key=l.tier_key WHERE l.festival_company_id=p_festival_company_id AND l.status IN('active','pending','suspended') ORDER BY t.rank DESC LIMIT 1),hi AS(SELECT * FROM eligible ORDER BY rank DESC LIMIT 1),nx AS(SELECT * FROM public.festival_licence_tiers WHERE rank=coalesce((SELECT rank FROM hi),0)+1) SELECT jsonb_build_object('current',(SELECT jsonb_build_object('key',tier_key,'name',display_name,'status',status) FROM current),'highestEligible',(SELECT jsonb_build_object('key',key,'name',display_name) FROM hi),'next',(SELECT jsonb_build_object('key',key,'name',display_name,'feeMinor',fee_minor) FROM nx),'requirements',coalesce((SELECT jsonb_agg(jsonb_build_object('code','upgrade_'||r.key,'description',replace(initcap(r.key),'_',' ')||' level '||r.value,'complete',coalesce(l.active_level,0)>=r.value::int)) FROM nx,jsonb_each_text(nx.requirements) r LEFT JOIN levels l ON l.category_key=r.key),'[]'))$$;
CREATE FUNCTION public.get_festival_upgrade_purchase_preview(p_festival_company_id uuid,p_category_key text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE s jsonb;c jsonb;BEGIN s:=public.get_festival_company_upgrades(p_festival_company_id);SELECT x INTO c FROM jsonb_array_elements(s->'categories') x WHERE x->>'key'=p_category_key;IF c IS NULL THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_CATEGORY_NOT_FOUND' USING ERRCODE='P0001';END IF;RETURN jsonb_build_object('category',c,'catalogueVersion',s->'catalogueVersion','companyVersion',s->'companyVersion','balanceMinor',s->'availableBalanceMinor','remainingBalanceMinor',greatest(0,(s->>'availableBalanceMinor')::bigint-(c->>'nextCostMinor')::bigint),'eligible',(c->>'affordable')::boolean AND NOT (c->>'delinquent')::boolean,'reasonCodes',CASE WHEN NOT (c->>'affordable')::boolean THEN '["FESTIVAL_UPGRADE_INSUFFICIENT_FUNDS"]'::jsonb WHEN (c->>'delinquent')::boolean THEN '["FESTIVAL_UPGRADE_DELINQUENT"]'::jsonb ELSE '[]'::jsonb END,'licenceImplications','[]'::jsonb);END$$;
CREATE FUNCTION public.purchase_festival_company_upgrade(p_festival_company_id uuid,p_category_key text,p_requested_level integer,p_expected_catalogue_version integer,p_expected_company_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_upgrade_actor();fc public.festival_companies%ROWTYPE;u public.festival_company_upgrades%ROWTYPE;l public.festival_upgrade_levels%ROWTYPE;op public.festival_upgrade_purchase_operations%ROWTYPE;v int;h text;tx uuid;result jsonb;BEGIN h:=encode(digest(jsonb_build_object('company',p_festival_company_id,'category',p_category_key,'level',p_requested_level,'catalogue',p_expected_catalogue_version,'companyVersion',p_expected_company_version)::text,'sha256'),'hex');SELECT * INTO op FROM public.festival_upgrade_purchase_operations WHERE actor_profile_id=a AND idempotency_key=p_idempotency_key;IF op.id IS NOT NULL THEN IF op.payload_hash<>h THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;IF op.status='succeeded' THEN RETURN op.result;END IF;END IF;SELECT * INTO fc FROM public.festival_companies WHERE id=p_festival_company_id FOR UPDATE;IF fc.id IS NULL OR NOT public._festival_upgrade_authorised(fc.id,a) THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_ACCESS_DENIED' USING ERRCODE='P0001';END IF;IF fc.upgrade_delinquent THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_DELINQUENT' USING ERRCODE='P0001';END IF;SELECT version INTO v FROM public.festival_upgrade_catalogue_versions WHERE status='published' AND retired_at IS NULL;IF v<>p_expected_catalogue_version THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_CATALOGUE_CHANGED' USING ERRCODE='P0001';END IF;IF fc.upgrade_version<>p_expected_company_version THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_VERSION_CONFLICT' USING ERRCODE='P0001';END IF;SELECT * INTO u FROM public.festival_company_upgrades WHERE festival_company_id=fc.id AND category_key=p_category_key FOR UPDATE;IF coalesce(u.owned_level,0)+1<>p_requested_level THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_LEVEL_SEQUENCE_INVALID' USING ERRCODE='P0001';END IF;IF u.status='building' THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_BUILD_IN_PROGRESS' USING ERRCODE='P0001';END IF;SELECT * INTO l FROM public.festival_upgrade_levels WHERE catalogue_version=v AND category_key=p_category_key AND level=p_requested_level AND active AND retired_at IS NULL;IF l.category_key IS NULL THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_LEVEL_NOT_FOUND' USING ERRCODE='P0001';END IF;IF EXISTS(SELECT 1 FROM public.festival_upgrade_prerequisites p LEFT JOIN public.festival_company_upgrades x ON x.festival_company_id=fc.id AND x.category_key=p.prerequisite_category_key WHERE p.catalogue_version=v AND p.category_key=p_category_key AND p.level=p_requested_level AND coalesce(x.active_level,0)<p.prerequisite_level) THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_PREREQUISITE_MISSING' USING ERRCODE='P0001';END IF;INSERT INTO public.festival_upgrade_purchase_operations(festival_company_id,actor_profile_id,category_key,requested_level,idempotency_key,payload_hash,status,catalogue_version,company_version,amount_minor) VALUES(fc.id,a,p_category_key,p_requested_level,p_idempotency_key,h,'processing',v,fc.upgrade_version,l.purchase_cost_minor) RETURNING * INTO op;BEGIN tx:=public.finance_debit_owner('company',fc.company_id,l.purchase_cost_minor,'company_expense','Festival upgrade: '||p_category_key,'festival-upgrade:'||op.id,a,jsonb_build_object('categoryKey',p_category_key,'level',p_requested_level,'catalogueVersion',v));EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE '%insufficient%' THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_INSUFFICIENT_FUNDS' USING ERRCODE='P0001';END IF;RAISE;END;INSERT INTO public.festival_company_upgrades(festival_company_id,category_key,catalogue_version,owned_level,active_level,status,build_started_at,build_completes_at,activated_at) VALUES(fc.id,p_category_key,v,p_requested_level,0,CASE WHEN l.build_duration=interval '0' THEN 'active' ELSE 'building' END,now(),now()+l.build_duration,CASE WHEN l.build_duration=interval '0' THEN now() END) ON CONFLICT(festival_company_id,category_key) DO UPDATE SET catalogue_version=v,owned_level=p_requested_level,status=excluded.status,build_started_at=now(),build_completes_at=excluded.build_completes_at,activated_at=excluded.activated_at,updated_at=now();IF l.build_duration=interval '0' THEN UPDATE public.festival_company_upgrades SET active_level=p_requested_level WHERE festival_company_id=fc.id AND category_key=p_category_key;END IF;UPDATE public.festival_companies SET upgrade_version=upgrade_version+1 WHERE id=fc.id;INSERT INTO public.festival_upgrade_effect_snapshots(purchase_operation_id,festival_company_id,category_key,owned_level,active_level,effective_level,effects,catalogue_version,aggregate_version,snapshot_hash) SELECT op.id,fc.id,p_category_key,owned_level,active_level,public._festival_effective_level(owned_level,active_level,missed_upkeep_weeks),l.effects,v,fc.upgrade_version+1,encode(digest((fc.id::text||p_category_key||p_requested_level||v),'sha256'),'hex') FROM public.festival_company_upgrades WHERE festival_company_id=fc.id AND category_key=p_category_key;INSERT INTO public.festival_upgrade_audit(festival_company_id,actor_profile_id,event_type,after_value) VALUES(fc.id,a,'upgrade_purchased',jsonb_build_object('category',p_category_key,'level',p_requested_level,'transactionId',tx));result:=public.get_festival_company_upgrades(fc.id);UPDATE public.festival_upgrade_purchase_operations SET status='succeeded',financial_transaction_id=tx,result=result,completed_at=now() WHERE id=op.id;RETURN result;END$$;
CREATE FUNCTION public.activate_completed_festival_upgrades(p_limit integer DEFAULT 100) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE n int;BEGIN WITH due AS(SELECT id FROM public.festival_company_upgrades WHERE status='building' AND build_completes_at<=now() ORDER BY build_completes_at FOR UPDATE SKIP LOCKED LIMIT p_limit) UPDATE public.festival_company_upgrades u SET status='active',active_level=owned_level,activated_at=now(),updated_at=now() FROM due WHERE u.id=due.id;GET DIAGNOSTICS n=ROW_COUNT;RETURN n;END$$;
CREATE FUNCTION public.process_festival_upgrade_upkeep(p_billing_period date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE x record;tx uuid;paid int:=0;unpaid int:=0;BEGIN FOR x IN SELECT u.*,fc.company_id,l.weekly_upkeep_minor FROM public.festival_company_upgrades u JOIN public.festival_companies fc ON fc.id=u.festival_company_id JOIN public.festival_upgrade_levels l ON l.catalogue_version=u.catalogue_version AND l.category_key=u.category_key AND l.level=u.owned_level WHERE u.status IN('active','building') LOOP INSERT INTO public.festival_upgrade_upkeep_obligations(festival_company_id,category_key,owned_level,billing_period,amount_minor,status,idempotency_reference) VALUES(x.festival_company_id,x.category_key,x.owned_level,p_billing_period,x.weekly_upkeep_minor,'due','festival-upkeep:'||x.festival_company_id||':'||x.category_key||':'||p_billing_period) ON CONFLICT DO NOTHING;IF NOT FOUND THEN CONTINUE;END IF;BEGIN tx:=public.finance_debit_owner('company',x.company_id,x.weekly_upkeep_minor,'company_expense','Festival upgrade weekly upkeep','festival-upkeep:'||x.festival_company_id||':'||x.category_key||':'||p_billing_period,NULL,jsonb_build_object('categoryKey',x.category_key,'billingPeriod',p_billing_period));UPDATE public.festival_upgrade_upkeep_obligations SET status='paid',financial_transaction_id=tx,paid_at=now() WHERE festival_company_id=x.festival_company_id AND category_key=x.category_key AND billing_period=p_billing_period;UPDATE public.festival_company_upgrades SET missed_upkeep_weeks=0 WHERE id=x.id;paid:=paid+1;EXCEPTION WHEN OTHERS THEN UPDATE public.festival_upgrade_upkeep_obligations SET status='unpaid',failure_reason='insufficient_funds' WHERE festival_company_id=x.festival_company_id AND category_key=x.category_key AND billing_period=p_billing_period;UPDATE public.festival_company_upgrades SET missed_upkeep_weeks=missed_upkeep_weeks+1 WHERE id=x.id;UPDATE public.festival_companies SET upgrade_delinquent=true WHERE id=x.festival_company_id;unpaid:=unpaid+1;END;END LOOP;RETURN jsonb_build_object('paid',paid,'unpaid',unpaid,'billingPeriod',p_billing_period);END$$;
CREATE FUNCTION public.snapshot_festival_edition_upgrades(p_edition_id uuid,p_festival_company_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE s jsonb;i uuid;v int;BEGIN s:=public.get_festival_company_upgrades(p_festival_company_id);v:=(s->>'companyVersion')::int;INSERT INTO public.festival_edition_upgrade_snapshots(edition_id,festival_company_id,catalogue_version,source_aggregate_version,licence_snapshot,levels,resolved_effects,delinquency_modifiers,snapshot_hash) VALUES(p_edition_id,p_festival_company_id,(s->>'catalogueVersion')::int,v,s->'licence',s->'categories',(SELECT jsonb_object_agg(x->>'key',x->'effects') FROM jsonb_array_elements(s->'categories') x),(SELECT jsonb_object_agg(x->>'key',jsonb_build_object('delinquent',x->'delinquent','effectiveLevel',x->'effectiveLevel')) FROM jsonb_array_elements(s->'categories') x),encode(digest(s::text,'sha256'),'hex')) ON CONFLICT(edition_id,snapshot_version) DO UPDATE SET edition_id=excluded.edition_id RETURNING id INTO i;RETURN i;END$$;
CREATE VIEW public.festival_upgrade_financial_reconciliation AS SELECT o.id,o.festival_company_id,o.category_key,o.requested_level,o.amount_minor purchase_amount_minor,t.gross_amount_minor transaction_amount_minor,coalesce((SELECT sum(amount_minor) FROM public.financial_ledger_entries WHERE transaction_id=t.id AND entry_direction='debit'),0) debit_minor,coalesce((SELECT sum(amount_minor) FROM public.financial_ledger_entries WHERE transaction_id=t.id AND entry_direction='credit'),0) credit_minor,o.status FROM public.festival_upgrade_purchase_operations o LEFT JOIN public.financial_transactions t ON t.id=o.financial_transaction_id;
CREATE FUNCTION public._reject_published_festival_catalogue_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF EXISTS(SELECT 1 FROM public.festival_upgrade_catalogue_versions WHERE version=coalesce(OLD.catalogue_version,NEW.catalogue_version) AND status='published') THEN RAISE EXCEPTION 'Published Festival upgrade catalogues are immutable';END IF;RETURN coalesce(NEW,OLD);END$$;
CREATE TRIGGER immutable_published_festival_levels BEFORE UPDATE OR DELETE ON public.festival_upgrade_levels FOR EACH ROW EXECUTE FUNCTION public._reject_published_festival_catalogue_mutation();
ALTER TABLE public.festival_upgrade_catalogue_versions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.festival_upgrade_categories ENABLE ROW LEVEL SECURITY;ALTER TABLE public.festival_upgrade_levels ENABLE ROW LEVEL SECURITY;ALTER TABLE public.festival_company_upgrades ENABLE ROW LEVEL SECURITY;ALTER TABLE public.festival_upgrade_purchase_operations ENABLE ROW LEVEL SECURITY;ALTER TABLE public.festival_upgrade_effect_snapshots ENABLE ROW LEVEL SECURITY;ALTER TABLE public.festival_upgrade_upkeep_obligations ENABLE ROW LEVEL SECURITY;ALTER TABLE public.festival_edition_upgrade_snapshots ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.festival_company_upgrades,public.festival_upgrade_purchase_operations,public.festival_upgrade_effect_snapshots,public.festival_upgrade_upkeep_obligations,public.festival_edition_upgrade_snapshots FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.purchase_festival_company_upgrade(uuid,text,integer,integer,integer,uuid),public.get_festival_company_upgrades(uuid),public.get_festival_upgrade_purchase_preview(uuid,text),public.get_festival_licence_progress(uuid),public.get_festival_upgrade_catalogue() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.purchase_festival_company_upgrade(uuid,text,integer,integer,integer,uuid),public.get_festival_company_upgrades(uuid),public.get_festival_upgrade_purchase_preview(uuid,text),public.get_festival_licence_progress(uuid),public.get_festival_upgrade_catalogue() TO authenticated;
REVOKE ALL ON FUNCTION public.activate_completed_festival_upgrades(integer),public.process_festival_upgrade_upkeep(date),public.snapshot_festival_edition_upgrades(uuid,uuid) FROM PUBLIC,anon,authenticated;
